'use strict';

// MODULES //

var sincos = require( '@stdlib/math/base/special/sincos' );
var TWO_PI = require( '@stdlib/constants/float64/two-pi' );
var decompose = require( './decompose.js' );


// VARIABLES //

var NTRYH = [ 3, 4, 2, 5 ]; // Initial trial factors for FFT factorization


// MAIN //

/**
* Initializes the working arrays for the FFT algorithm.
*
* @private
* @param {number} n - length of the sequence
* @param {Float64Array} wa - array of twiddle factors
* @param {number} wptr - starting index for wa
* @param {Int32Array} ifac - array containing factorization information
* @param {number} ifptr - starting index for ifac
* @returns {void}
*/
function cffti1( n, wa, wptr, ifac, ifptr ) {
	var argld;
	var argh;
	var idot;
	var ipm;
	var ido;
	var arg;
	var nf;
	var ip;
	var ii;
	var ld;
	var fi;
	var l2;
	var l1;
	var k1;
	var i1;
	var sc;
	var j;
	var i;

	ifptr -= 1;
	wptr -= 1;

	nf = decompose( n, ifac, ifptr, NTRYH );
	argh = TWO_PI / n;
	i = 2;
	l1 = 1;
	for ( k1 = 1; k1 <= nf; k1++ ) {
		ip = ifac[ ifptr + k1 + 2 ];
		ld = 0;
		l2 = ip * l1;
		ido = n / l2;
		idot = ido + ido + 2;
		ipm = ip - 1;
		for ( j = 1; j <= ipm; j++ ) {
			i1 = i;
			wa[ wptr + i - 1 ] = 1.0;
			wa[ wptr + i ] = 0.0;
			ld += l1;
			fi = 0.0;
			argld = ld * argh;
			for ( ii = 4; ii <= idot; ii += 2 ) {
				i += 2;
				fi += 1.0;
				arg = fi * argld;
				sc = sincos( arg );
				wa[ wptr + i - 1 ] = sc[ 1 ];
				wa[ wptr + i ] = sc[ 0 ];
			}
			if ( ip > 5 ) {
				wa[ wptr + i1 - 1 ] = wa[ wptr + i - 1 ];
				wa[ wptr + i1 ] = wa[ wptr + i ];
			}
		}

		l1 = l2;
	}
}


// EXPORTS //

module.exports = cffti1;
